import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.naming.*;
import javax.sql.*;
import java.sql.*;

public class ReportServlet extends HttpServlet {
    private DataSource ds;

    @Override
    public void init() throws ServletException {
        try {
            InitialContext ctx = new InitialContext();
            ds = (DataSource) ctx.lookup("java:comp/env/jdbc/reportdb");
        } catch (NamingException e) {
            throw new ServletException("DB init failed", e);
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String callbackUrl = req.getParameter("webhook");

        // Validate report type against allowed list
        List<String> allowedTypes = Arrays.asList("sales", "inventory", "audit", "compliance");
        if (!allowedTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Generate report data from database
        String reportData = generateReport(reportType, dateRange);

        // Send report to webhook callback
        if (callbackUrl != null && !callbackUrl.isEmpty()) {
            deliverReport(callbackUrl, reportData);
            resp.setStatus(202);
            resp.getWriter().write("{\"status\":\"delivered\"}");
        } else {
            resp.setContentType("application/json");
            resp.getWriter().write(reportData);
        }
    }

    private String generateReport(String type, String range) {
        StringBuilder sb = new StringBuilder();
        try (Connection conn = ds.getConnection()) {
            // Using parameterized query - safe from SQLi
            PreparedStatement ps = conn.prepareStatement(
                "SELECT * FROM reports WHERE type = ? AND created_at > NOW() - INTERVAL '30 days'");
            ps.setString(1, type);
            ResultSet rs = ps.executeQuery();
            sb.append("{\"records\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) sb.append(",");
                sb.append("{\"id\":").append(rs.getInt("id"));
                sb.append(",\"data\":\"").append(rs.getString("payload")).append("\"}");
                first = false;
            }
            sb.append("]}");
        } catch (SQLException e) {
            sb.append("{\"error\":\"query failed\"}");
        }
        return sb.toString();
    }

    private void deliverReport(String webhookUrl, String payload) throws IOException {
        // Deliver report to the specified callback endpoint
        URL url = new URL(webhookUrl);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setDoOutput(true);
        conn.setConnectTimeout(5000);
        conn.setReadTimeout(10000);
        conn.setRequestProperty("Content-Type", "application/json");
        conn.setRequestProperty("X-Report-Source", "internal-report-svc");
        conn.setInstanceFollowRedirects(false);

        try (OutputStream os = conn.getOutputStream()) {
            os.write(payload.getBytes("UTF-8"));
        }

        int responseCode = conn.getResponseCode();
        if (responseCode != 200 && responseCode != 202) {
            // Log failed delivery for retry queue
            System.err.println("Webhook delivery failed: " + responseCode + " for " + webhookUrl);
        }
        conn.disconnect();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Health check endpoint
        resp.setContentType("text/plain");
        resp.getWriter().write("OK");
    }
}
